-- Adminer 6.1.1 PostgreSQL 16.14 dump

CREATE DATABASE "qualicontact";
\connect "qualicontact";

CREATE SCHEMA IF NOT EXISTS "public";
SET search_path TO "public";

DROP TABLE IF EXISTS "app_audit_log", "app_permissions", "app_role_permissions", "app_roles", "app_sessions", "app_user_roles", "app_users", "crm_state", "local_audio_objects";

CREATE TABLE "app_audit_log" (
    "id" bigserial NOT NULL,
    "happened_at" timestamptz DEFAULT now() NOT NULL,
    "actor_id" text,
    "action" text NOT NULL,
    "target_type" text NOT NULL,
    "target_id" text,
    "details" jsonb DEFAULT '{}' NOT NULL,
    "request_id" text,
    CONSTRAINT "app_audit_log_pkey" PRIMARY KEY ("id")
);

CREATE INDEX app_audit_actor_time_idx ON "app_audit_log" USING btree (actor_id, happened_at DESC);


CREATE TABLE "app_permissions" (
    "code" text NOT NULL,
    "label" text NOT NULL,
    "permission_group" text NOT NULL,
    "description" text DEFAULT '' NOT NULL,
    "is_api" boolean DEFAULT false NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "app_permissions_pkey" PRIMARY KEY ("code")
);


CREATE TABLE "app_role_permissions" (
    "role_id" text NOT NULL,
    "permission_code" text NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "app_role_permissions_pkey" PRIMARY KEY ("role_id", "permission_code")
);


CREATE TABLE "app_roles" (
    "id" text NOT NULL,
    "code" text NOT NULL,
    "name" text NOT NULL,
    "description" text DEFAULT '' NOT NULL,
    "scope" text DEFAULT 'organization' NOT NULL,
    "is_system" boolean DEFAULT false NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "app_roles_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "app_roles_scope_check" CHECK (((scope = ANY (ARRAY['organization'::text, 'assigned_client'::text]))))
);

CREATE UNIQUE INDEX app_roles_code_key ON "app_roles" USING btree (code);


CREATE TABLE "app_sessions" (
    "token_hash" character(64) NOT NULL,
    "user_id" text NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "expires_at" timestamptz NOT NULL,
    "last_seen_at" timestamptz DEFAULT now() NOT NULL,
    "user_agent" text,
    "ip_address" inet,
    CONSTRAINT "app_sessions_pkey" PRIMARY KEY ("token_hash")
);

CREATE INDEX app_sessions_expiry_idx ON "app_sessions" USING btree (expires_at);


CREATE TABLE "app_user_roles" (
    "user_id" text NOT NULL,
    "role_id" text NOT NULL,
    "client_id" text,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "assigned_by" text
);

CREATE UNIQUE INDEX app_user_roles_scope_uq ON "app_user_roles" USING btree (user_id, role_id, COALESCE(client_id, ''::text));

CREATE INDEX app_user_roles_user_idx ON "app_user_roles" USING btree (user_id) WHERE active;


CREATE TABLE "app_users" (
    "id" text NOT NULL,
    "email" text NOT NULL,
    "full_name" text NOT NULL,
    "password_hash" text NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "must_change_password" boolean DEFAULT false NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    "last_login_at" timestamptz,
    CONSTRAINT "app_users_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX app_users_email_lower_uq ON "app_users" USING btree (lower(email));


CREATE TABLE "crm_state" (
    "id" text NOT NULL,
    "data" jsonb NOT NULL,
    "version" bigint DEFAULT '1' NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    "updated_by" text,
    CONSTRAINT "crm_state_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "crm_state_id_check" CHECK (((id = 'main'::text)))
);


CREATE TABLE "local_audio_objects" (
    "id" text NOT NULL,
    "object_key" text NOT NULL,
    "sha256" character(64) NOT NULL,
    "original_name" text NOT NULL,
    "mime_type" text NOT NULL,
    "byte_size" bigint NOT NULL,
    "media_kind" text NOT NULL,
    "record_id" text,
    "client_id" text,
    "uploaded_by" text,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "local_audio_objects_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "local_audio_objects_byte_size_check" CHECK (((byte_size >= 0))),
    CONSTRAINT "local_audio_objects_media_kind_check" CHECK (((media_kind = ANY (ARRAY['call_record'::text, 'debrief'::text]))))
);

CREATE UNIQUE INDEX local_audio_objects_object_key_key ON "local_audio_objects" USING btree (object_key);

CREATE UNIQUE INDEX local_audio_hash_kind_uq ON "local_audio_objects" USING btree (sha256, media_kind, COALESCE(record_id, ''::text), COALESCE(client_id, ''::text));

CREATE INDEX local_audio_record_idx ON "local_audio_objects" USING btree (record_id);


ALTER TABLE ONLY "app_audit_log" ADD CONSTRAINT "app_audit_log_actor_id_fkey" FOREIGN KEY (actor_id) REFERENCES "app_users"(id) ON DELETE SET NULL;

ALTER TABLE ONLY "app_role_permissions" ADD CONSTRAINT "app_role_permissions_permission_code_fkey" FOREIGN KEY (permission_code) REFERENCES "app_permissions"(code) ON DELETE CASCADE;
ALTER TABLE ONLY "app_role_permissions" ADD CONSTRAINT "app_role_permissions_role_id_fkey" FOREIGN KEY (role_id) REFERENCES "app_roles"(id) ON DELETE CASCADE;

ALTER TABLE ONLY "app_sessions" ADD CONSTRAINT "app_sessions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES "app_users"(id) ON DELETE CASCADE;

ALTER TABLE ONLY "app_user_roles" ADD CONSTRAINT "app_user_roles_assigned_by_fkey" FOREIGN KEY (assigned_by) REFERENCES "app_users"(id) ON DELETE SET NULL;
ALTER TABLE ONLY "app_user_roles" ADD CONSTRAINT "app_user_roles_role_id_fkey" FOREIGN KEY (role_id) REFERENCES "app_roles"(id) ON DELETE RESTRICT;
ALTER TABLE ONLY "app_user_roles" ADD CONSTRAINT "app_user_roles_user_id_fkey" FOREIGN KEY (user_id) REFERENCES "app_users"(id) ON DELETE CASCADE;

ALTER TABLE ONLY "crm_state" ADD CONSTRAINT "crm_state_updated_by_fkey" FOREIGN KEY (updated_by) REFERENCES "app_users"(id) ON DELETE SET NULL;

ALTER TABLE ONLY "local_audio_objects" ADD CONSTRAINT "local_audio_objects_uploaded_by_fkey" FOREIGN KEY (uploaded_by) REFERENCES "app_users"(id) ON DELETE SET NULL;

